<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);if(isset($_GET['read'])){$pdo->prepare('UPDATE notifications SET read_at=COALESCE(read_at,NOW()) WHERE id=? AND user_id=?')->execute([(int)$_GET['read'],$u['id']]);header('Location:/notifications.php');exit;}$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 200');$q->execute([$u['id']]);$items=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/home.php">Home</a><a href="/explore.php">Explore</a><a href="/research.php">Research</a><a href="/teams.php">Teams</a></nav></header><main class="panel article"><span class="eyebrow">NOTIFICATIONS</span><h1>What changed</h1><?php if(!$items):?><div class="card empty">No notifications yet.</div><?php endif?><?php foreach($items as $n):?><article class="card <?=$n['read_at']?'':'unreadCard'?>"><div class="meta"><?=h(str_replace('_',' ',ucwords($n['notification_type'],'_')))?> · <?=h($n['created_at'])?></div><p><?=h($n['body'])?></p><div class="inlineActions"><?php if($n['object_type']==='annotation'&&$n['object_public_id']):?><a href="/annotation.php?id=<?=h($n['object_public_id'])?>">Open annotation</a><?php elseif($n['object_type']==='source'&&$n['object_public_id']):?><a href="/source.php?id=<?=h($n['object_public_id'])?>">Open source</a><?php endif?><?php if(!$n['read_at']):?><a href="/notifications.php?read=<?=h((string)$n['id'])?>">Mark read</a><?php endif?></div></article><?php endforeach?></main></body></html>